let current_sentence := "";

let i := 0;
let len := length(text);

while (i < len) {
    let char := substring(text, i, 1);

    if (char == " ") {
        if (length(current_word) > 0) {
            words := append(words, current_word);
            word_count := word_count + 1;
            current_word := "";
        }
        current_sentence := current_sentence + " ";
    } else if (char == "." || char == "!" || char == "?") {
        if (length(current_word) > 0) {
            words := append(words, current_word);
            word_count := word_count + 1;
            current_word := "";
        }
        current_sentence := current_sentence + char;
        sentences := append(sentences, current_sentence);
        sentence_count := sentence_count + 1;
        current_sentence := "";
    } else {
        current_word := current_word + char;
        current_sentence := current_sentence + char;
    }

    i := i + 1;
}

