import statistics;

let text := "Epidemiological surveillance indicates a declining trend in new infections over the past seven days. Case fatality rate remains stable at two point three percent across all affected regions.";

let word_count := 0;
let sentence_count := 0;
let readability_score := 0.0;
let sentiment := "neutral";

let words := text.split(" ");
for (let i := 0; i < length(words); i := i + 1) {
    word_count := word_count + 1;
}

let sentences := text.split(". ");
sentence_count := length(sentences);

let avg_word_length := 0.0;
if (word_count > 0) {
    let total_chars := 0;
    for (let i := 0; i < length(words); i := i + 1) {
        let w := words[i];
        total_chars := total_chars + length(w);
    }
    avg_word_length := total_chars / real(word_count);
}

readability_score := 0.0;
if (sentence_count > 0) {
    readability_score := 0.39 * real(word_count) / real(sentence_count) - 0.058 * avg_word_length;
}

if (readability_score < 12) {
    sentiment := "complex";
} else if (readability_score > 20) {
    sentiment := "simple";
} else {
    sentiment := "neutral";
}

println("Word count: " + word_count);
println("Sentence count: " + sentence_count);
println("Readability score: " + readability_score);
println("Sentiment: " + sentiment);

