import healthcare;

let ds := new Data { name := "heal_pa_2" };

func is_high_risk(patient) {
    let bp := patient.blood_pressure;
    let ch := patient.total_cholesterol;
    let hr := patient.heart_rate;
    let hba1c := patient.hba1c;
    let history := patient.medical_history;

    let high_bp := (bp >= 140);
    let high_ch := (ch >= 200);
    let high_hr := (hr >= 100);
    let high_hba1c := (hba1c >= 6.5);
    let has_hypertension := (history contains "hypertension");
    let has_diabetes := (history contains "diabetes");

    let risk_score := 0;

    if (high_bp) {
        risk_score := risk_score + 2;
    }
    if (high_ch) {
        risk_score := risk_score + 2;
    }
    if (high_hr) {
        risk_score := risk_score + 1;
    }
    if (high_hba1c) {
        risk_score := risk_score + 2;
    }
    if (has_hypertension) {
        risk_score := risk_score + 1;
    }
    if (has_diabetes) {
        risk_score := risk_score + 1;
    }

    return (risk_score >= 3);
}

let filtered_patients := [];
let count := 0;

for (let i := 0; i < ds.count; i := i + 1) {
    let p := ds.get(i);
    let risk := is_high_risk(p);
    if (risk) {
        filtered_patients := filtered_patients + [p];
        count := count + 1;
    }
}

let result := filter_patients_by_risk(ds, filtered_patients);
commit_result("high_cvd_risk", result);

